PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE categories (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL,
  position INTEGER NOT NULL DEFAULT 0,
  parent_id INTEGER REFERENCES categories(id) ON DELETE CASCADE,
  depth INTEGER NOT NULL DEFAULT 0,
  is_private INTEGER DEFAULT 0,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(name, parent_id)
);
CREATE TABLE bookmarks (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL,
  url TEXT NOT NULL,
  description TEXT,
  icon TEXT,
  category_id INTEGER NOT NULL,
  position INTEGER NOT NULL DEFAULT 0,
  is_private INTEGER DEFAULT 0,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP, tags TEXT DEFAULT '', notes TEXT DEFAULT '',
  FOREIGN KEY (category_id) REFERENCES categories(id) ON DELETE CASCADE
);
CREATE TABLE settings (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  key TEXT NOT NULL UNIQUE,
  value TEXT NOT NULL,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_bookmarks_category_position 
ON bookmarks(category_id, position);
CREATE INDEX idx_bookmarks_private 
ON bookmarks(is_private);
CREATE INDEX idx_bookmarks_url 
ON bookmarks(url);
CREATE INDEX idx_categories_position 
ON categories(position);
CREATE INDEX idx_categories_parent_id 
ON categories(parent_id);
CREATE INDEX idx_categories_parent_position 
ON categories(parent_id, position);
CREATE INDEX idx_categories_private 
ON categories(is_private);
CREATE INDEX idx_settings_key 
ON settings(key);
